  "Auto resolves the current Collinear unit type; CDS and locus require that exact unit type.": "“อัตโนมัติ” จะระบุประเภทหน่วย Collinear ปัจจุบัน “CDS” และ “โลคัส” ต้องใช้หน่วยประเภทนั้นโดยเฉพาะ",
  "Auto shows these fields throughout the diagram": "“อัตโนมัติ” แสดงฟิลด์เหล่านี้ทั่วทั้งแผนภาพ",
