  "Custom stack geometry is active. Use each Depth row width, or Reset to copy this value into the stack.": "กำลังใช้ขนาดและรูปทรงของสแต็กที่กำหนดเอง ให้ใช้ความกว้างของแถว “ความลึก” แต่ละแถว หรือคลิก “รีเซ็ต” เพื่อคัดลอกค่านี้ไปยังสแต็ก",
  "Custom stack geometry is active. Use the Dinucleotide content row radius, or Reset to copy this value into the stack.": "กำลังใช้ขนาดและรูปทรงของสแต็กที่กำหนดเอง ให้ใช้รัศมีของแถว “ปริมาณไดนิวคลีโอไทด์” หรือคลิก “รีเซ็ต” เพื่อคัดลอกค่านี้ไปยังสแต็ก",
  "Custom stack geometry is active. Use the Dinucleotide content row width, or Reset to copy this value into the stack.": "กำลังใช้ขนาดและรูปทรงของสแต็กที่กำหนดเอง ให้ใช้ความกว้างของแถว “ปริมาณไดนิวคลีโอไทด์” หรือคลิก “รีเซ็ต” เพื่อคัดลอกค่านี้ไปยังสแต็ก",
  "Custom stack geometry is active. Use the Dinucleotide skew row radius, or Reset to copy this value into the stack.": "กำลังใช้ขนาดและรูปทรงของสแต็กที่กำหนดเอง ให้ใช้รัศมีของแถว “skew ของไดนิวคลีโอไทด์” หรือคลิก “รีเซ็ต” เพื่อคัดลอกค่านี้ไปยังสแต็ก",
