  "Edit the explicit linear track stack. Opening or closing this panel does not enable or alter the stack. Arrows reorder within the current side; Row actions move rows across the boundary.": "แก้ไขสแต็กแทร็กที่กำหนดเองของแผนภาพแบบเส้นตรง การเปิดหรือปิดแผงนี้จะไม่เปิดใช้หรือเปลี่ยนแปลงสแต็ก ปุ่มลูกศรจะจัดลำดับใหม่ภายในด้านปัจจุบัน ส่วน “การดำเนินการของแถว” จะย้ายแถวข้ามเส้นแบ่ง",
