  "Font {family} could not be prepared for the PDF. Its text is drawn in {substitute}.": "เตรียมแบบอักษร {family} สำหรับ PDF ไม่ได้ ข้อความที่ใช้แบบอักษรนี้จะวาดด้วย {substitute}",
