  "Font {family} is not embedded: its license (OS/2 fsType) does not allow embedding. The SVG shows it only where {family} is installed.": "ไม่ได้ฝังแบบอักษร {family} เนื่องจากใบอนุญาตของแบบอักษร (OS/2 fsType) ไม่อนุญาตให้ฝัง SVG จะแสดงแบบอักษรนี้เฉพาะในเครื่องที่ติดตั้ง {family} ไว้",
  "Fonts loaded in this page could not be prepared again for drawing. Load them again in Font, or choose another font.": "เตรียมแบบอักษรที่โหลดในหน้านี้ใหม่เพื่อใช้วาดไม่ได้ โหลดแบบอักษรอีกครั้งในส่วน “แบบอักษร” หรือเลือกแบบอักษรอื่น",
