  "Legend: the entry stored under \"{label}\" ({path}) sets the row \"{used}\", which a later edit also sets; the later edit is used and this one was dropped.": "คำอธิบายสัญลักษณ์: รายการที่เก็บไว้ภายใต้ “{label}” ({path}) กำหนดค่าแถว “{used}” ซึ่งการแก้ไขที่มาทีหลังก็กำหนดค่าด้วย จึงใช้การแก้ไขที่มาทีหลังและทิ้งรายการนี้ไป",
  "Legend: the position \"{stored}\" ({path}) is not one of its mode's positions; it is not used.": "คำอธิบายสัญลักษณ์: ตำแหน่ง “{stored}” ({path}) ไม่ใช่ตำแหน่งของโหมดนั้น จึงไม่ได้ใช้",
