  "Live edit failed: direct edits already applied are kept; geometry may still need updating.": "การแก้ไขแบบเรียลไทม์ไม่สำเร็จ: การแก้ไขโดยตรงที่นำไปใช้แล้วยังคงอยู่ แต่รูปทรงและตำแหน่งอาจยังต้องอัปเดต",
  "Live edit: feature color, label text, and visibility update the current Result; geometry may rerender automatically.": "การแก้ไขแบบเรียลไทม์: สีฟีเจอร์ ข้อความป้ายกำกับ และการมองเห็นจะอัปเดตผลลัพธ์ปัจจุบัน ส่วนรูปทรงและตำแหน่งอาจวาดใหม่โดยอัตโนมัติ",
