  "Name of the Depth series this row draws. Typing renames the series everywhere: its series card, every row that draws it, and the legend. Leave blank for the default name: Depth, or Depth N when there are several series.": "ชื่อของชุดข้อมูลความลึกที่แถวนี้วาด เมื่อพิมพ์ ชื่อชุดข้อมูลจะเปลี่ยนในทุกที่ ได้แก่ การ์ดชุดข้อมูล ทุกแถวที่วาดชุดข้อมูลนี้ และคำอธิบายสัญลักษณ์ เว้นว่างไว้เพื่อใช้ชื่อเริ่มต้น คือ Depth หรือ Depth N เมื่อมีหลายชุดข้อมูล",
  "Name of the Depth series this row draws. Typing renames the series everywhere: its series card, every row that draws it, and the legend. The legend lists series in custom-stack order and omits series that no enabled row draws. Leave blank for the default name: Depth, or Depth N when there are several series.": "ชื่อของชุดข้อมูลความลึกที่แถวนี้วาด เมื่อพิมพ์ ชื่อชุดข้อมูลจะเปลี่ยนในทุกที่ ได้แก่ การ์ดชุดข้อมูล ทุกแถวที่วาดชุดข้อมูลนี้ และคำอธิบายสัญลักษณ์ คำอธิบายสัญลักษณ์จะแสดงชุดข้อมูลตามลำดับในสแต็กที่กำหนดเอง และไม่แสดงชุดข้อมูลที่ไม่มีแถวใดซึ่งเปิดใช้อยู่วาด เว้นว่างไว้เพื่อใช้ชื่อเริ่มต้น คือ Depth หรือ Depth N เมื่อมีหลายชุดข้อมูล",
  "Name of this Depth series in the legend. The legend label field of every Depth row that draws this series edits the same name. Leave blank for the default name: Depth, or Depth N when there are several series.": "ชื่อของชุดข้อมูลความลึกนี้ในคำอธิบายสัญลักษณ์ ฟิลด์ “ป้ายกำกับในคำอธิบายสัญลักษณ์” ในทุกแถวความลึกที่วาดชุดข้อมูลนี้จะแก้ไขชื่อเดียวกัน เว้นว่างไว้เพื่อใช้ชื่อเริ่มต้น คือ Depth หรือ Depth N เมื่อมีหลายชุดข้อมูล",
