  "Row gap ratio": "อัตราส่วนช่องว่างระหว่างแถว",
  "Rows above Axis are outside the circular axis; rows below Axis are inside it. Arrow buttons reorder within the current side only. Use Move outside or Move inside to cross the Axis.": "แถวที่อยู่เหนือแกนจะอยู่ด้านนอกแกนวงกลม และแถวที่อยู่ใต้แกนจะอยู่ด้านใน ปุ่มลูกศรจัดลำดับใหม่ได้เฉพาะภายในด้านปัจจุบัน ใช้ “ย้ายไปด้านนอกแกน” หรือ “ย้ายไปด้านในแกน” เพื่อย้ายข้ามแกน",
  "Rows before Axis render above it; rows after Axis render below it. A Depth slot selects one global series and does not control vertical order. Records with a blank TSV cell do not paint that series, while its stack space remains reserved.": "แถวก่อนแกนจะวาดเหนือแกน และแถวหลังแกนจะวาดใต้แกน ช่องความลึกเลือกชุดข้อมูลส่วนกลาง 1 ชุดและไม่ได้ควบคุมลำดับในแนวตั้ง ระเบียนที่มีเซลล์ TSV ว่างจะไม่วาดชุดข้อมูลนั้น แต่ยังคงสงวนพื้นที่ในสแต็กไว้",
