  "Ruler label color": "สีป้ายกำกับไม้บรรทัด",
  "Ruler on Axis": "ไม้บรรทัดบนแกน",
  "Rules are evaluated from top to bottom. Off hides the feature and leaves it out of protein search; Leave out of protein search keeps its visibility and leaves it out of protein search.": "ระบบประเมินกฎจากบนลงล่าง “ปิด” จะซ่อนฟีเจอร์และละเว้นจากการค้นหาโปรตีน ส่วน “ละเว้นจากการค้นหาโปรตีน” จะคงการมองเห็นไว้และละเว้นจากการค้นหาโปรตีน",
  "Rules on the same qualifier: the first match wins.": "กฎที่ใช้ qualifier เดียวกัน: กฎแรกที่ตรงกันจะมีผล",
  "Run LOSAT": "เรียกใช้ LOSAT",
  "Run LOSAT for all adjacent pairs": "เรียกใช้ LOSAT สำหรับทุกคู่ที่อยู่ติดกัน",
  "Run LOSAT requires at least 2 loaded sequences.": "ต้องโหลดลำดับอย่างน้อย 2 ลำดับจึงจะ “เรียกใช้ LOSAT” ได้",
  "Run info": "ข้อมูลการเรียกใช้",
  "Run info is available after a successful manual generation.": "ข้อมูลการเรียกใช้จะพร้อมใช้งานหลังจากสร้างด้วยตนเองสำเร็จ",
