  "Running {program} comparisons for the circular diagram: {completed}/{total} jobs complete": "กำลังเรียกใช้การเปรียบเทียบด้วย {program} สำหรับแผนภาพแบบวงกลม: งานเสร็จแล้ว {completed}/{total}",
  "SPECIFIC RULES": "กฎเฉพาะ",
  "SVG ID": "รหัส SVG",
  "SVG and Interactive SVG exports carry the characters they use of this font, so they show it on computers without it. Fonts whose license forbids embedding are not embedded. Turned off, the SVG files keep only the font name. PNG export always draws this font, whatever this setting and the font's license. PDF export embeds this font whatever this setting; a font whose license forbids embedding is drawn in the nearest Liberation font.": "เมื่อส่งออกเป็น SVG หรือ SVG แบบอินเทอร์แอกทีฟ ระบบจะฝังเฉพาะอักขระของแบบอักษรนี้ที่ใช้จริง ไฟล์จึงแสดงผลได้แม้บนคอมพิวเตอร์ที่ไม่มีแบบอักษรนี้ ระบบจะไม่ฝังแบบอักษรที่ใบอนุญาตห้ามฝัง เมื่อปิด ไฟล์ SVG จะเก็บไว้เฉพาะชื่อแบบอักษร การส่งออก PNG จะวาดด้วยแบบอักษรนี้เสมอ ไม่ว่าการตั้งค่านี้หรือใบอนุญาตของแบบอักษรจะเป็นอย่างไร การส่งออก PDF จะฝังแบบอักษรนี้ไม่ว่าการตั้งค่านี้จะเป็นอย่างไร ส่วนแบบอักษรที่ใบอนุญาตห้ามฝังจะวาดด้วยแบบอักษร Liberation ที่ใกล้เคียงที่สุด",
