  "Save Session": "บันทึกเซสชัน",
  "Save Session afterwards writes the current format. The file itself is not changed.": "หากคลิก “บันทึกเซสชัน” หลังจากนี้ ระบบจะเขียนไฟล์ในรูปแบบปัจจุบัน ไฟล์เดิมจะไม่เปลี่ยนแปลง",
  "Save Session needs current feature metadata for the loaded Result. Generate once, then Save Session.": "“บันทึกเซสชัน” ต้องใช้ข้อมูลเมตาของฟีเจอร์ล่าสุดของผลลัพธ์ที่โหลด คลิก “สร้าง” 1 ครั้ง แล้วจึงคลิก “บันทึกเซสชัน”",
  "Save stores the current Result and generation settings draft. It does not Generate.": "“บันทึกเซสชัน” จะเก็บผลลัพธ์ปัจจุบันและฉบับร่างการตั้งค่าการสร้าง แต่จะไม่สร้างแผนภาพ",
  "Save stores the current Result and settings draft. Export outputs the current Result. Neither applies pending settings.": "“บันทึกเซสชัน” จะเก็บผลลัพธ์ปัจจุบันและฉบับร่างการตั้งค่า “ส่งออก” จะส่งออกผลลัพธ์ปัจจุบัน ทั้งสองอย่างไม่นำการตั้งค่าที่รอดำเนินการไปใช้",
  "Save the current Result and settings draft without generating": "บันทึกผลลัพธ์ปัจจุบันและฉบับร่างการตั้งค่าโดยไม่สร้างแผนภาพ",
  "Saved Circular diagram: its settings ({path}) could not be read; that diagram and its Results are left out.": "แผนภาพแบบวงกลมที่บันทึกไว้: อ่านการตั้งค่า ({path}) ไม่ได้ จึงละเว้นแผนภาพนั้นและผลลัพธ์ของแผนภาพไว้",
  "Saved Linear diagram: its settings ({path}) could not be read; that diagram and its Results are left out.": "แผนภาพแบบเส้นตรงที่บันทึกไว้: อ่านการตั้งค่า ({path}) ไม่ได้ จึงละเว้นแผนภาพนั้นและผลลัพธ์ของแผนภาพไว้",
  "Saved alignment needs repair.": "ต้องซ่อมแซมการจัดแนวที่บันทึกไว้",
  "Saved comparison needs a decision": "ต้องตัดสินใจเกี่ยวกับการเปรียบเทียบที่บันทึกไว้",
  "Saved comparison preserved as read-only": "เก็บการเปรียบเทียบที่บันทึกไว้เป็นแบบอ่านอย่างเดียวแล้ว",
  "Saved diagram: the settings of the saved diagram ({path}) could not be read. The file loads as settings only; the saved Results, the GenBank, GFF and FASTA inputs, the feature list and the caches are left out.": "แผนภาพที่บันทึกไว้: อ่านการตั้งค่าของแผนภาพที่บันทึกไว้ ({path}) ไม่ได้ ระบบจะโหลดไฟล์เป็นการตั้งค่าเท่านั้น และละเว้นผลลัพธ์ที่บันทึกไว้ อินพุต GenBank, GFF และ FASTA รายการฟีเจอร์ รวมถึงแคช",
  "Saved names waiting for their original members: {names}": "ชื่อที่บันทึกไว้ซึ่งยังไม่พบสมาชิกเดิม: {names}",
  "Saved other diagram: its settings ({path}) could not be read; that diagram and its Results are left out.": "แผนภาพอื่นที่บันทึกไว้: อ่านการตั้งค่า ({path}) ไม่ได้ จึงละเว้นแผนภาพนั้นและผลลัพธ์ของแผนภาพไว้",
  "Saving session. Retry after saving finishes.": "กำลังบันทึกเซสชัน ลองอีกครั้งหลังจากบันทึกเสร็จ",
