  "Select Hide GC Content, or reduce GC Content Width (with Custom Track Slots on, the row width).": "เลือก “ซ่อนปริมาณ GC” หรือลด “ความกว้างปริมาณ GC” (เมื่อเปิด “ช่องแทร็กที่กำหนดเอง” ให้ลดความกว้างของแถว)",
  "Select Hide GC Skew, or reduce GC Skew Width (with Custom Track Slots on, the row width).": "เลือก “ซ่อน GC skew” หรือลด “ความกว้าง GC skew” (เมื่อเปิด “ช่องแทร็กที่กำหนดเอง” ให้ลดความกว้างของแถว)",
  "Select a row to edit its label or open its details.": "เลือกแถวเพื่อแก้ไขป้ายกำกับหรือเปิดรายละเอียด",
