  "Select an eligible enabled anchor for an annotation track whose placement is Overlay anchor (Circular) or On axis (Linear).": "เลือกจุดยึดที่เปิดใช้อยู่และเข้าข่าย สำหรับแทร็กคำอธิบายประกอบที่ตั้งการวางเป็น “ซ้อนทับบนจุดยึด” (แบบวงกลม) หรือ “บนแกน” (แบบเส้นตรง)",
