  "Settings: a part ({path}) could not be read and was left out, with the settings inside it.": "การตั้งค่า: ส่วนหนึ่ง ({path}) อ่านไม่ได้จึงละเว้นไว้พร้อมกับการตั้งค่าภายในส่วนนั้น",
  "Settings: a part ({path}) could not be read; its default is used.": "การตั้งค่า: ส่วนหนึ่ง ({path}) อ่านไม่ได้ จึงใช้ค่าเริ่มต้นแทน",
  "Settings: the value \"{stored}\" ({path}) cannot be used; it is changed.": "การตั้งค่า: ใช้ค่า “{stored}” ({path}) ไม่ได้ ระบบจึงเปลี่ยนค่านี้",
  "Settings: the value \"{stored}\" ({path}) cannot be used; it is left unset.": "การตั้งค่า: ใช้ค่า “{stored}” ({path}) ไม่ได้ จึงเว้นไว้โดยไม่ตั้งค่า",
  "Settings: the value \"{stored}\" ({path}) cannot be used; its default is used.": "การตั้งค่า: ใช้ค่า “{stored}” ({path}) ไม่ได้ จึงใช้ค่าเริ่มต้นแทน",
  "Settings: the value \"{stored}\" ({path}) cannot be used; the drawing keeps its current value.": "การตั้งค่า: ใช้ค่า “{stored}” ({path}) ไม่ได้ ภาพวาดจึงคงค่าปัจจุบันไว้",
  "Settings: the value \"{stored}\" ({path}) cannot be used; {used} is used.": "การตั้งค่า: ใช้ค่า “{stored}” ({path}) ไม่ได้ จึงใช้ {used} แทน",
  "Settings: the value of {path} cannot be used; it is changed.": "การตั้งค่า: ใช้ค่าของ {path} ไม่ได้ ระบบจึงเปลี่ยนค่านี้",
  "Settings: the value of {path} cannot be used; it is left unset.": "การตั้งค่า: ใช้ค่าของ {path} ไม่ได้ จึงเว้นไว้โดยไม่ตั้งค่า",
  "Settings: the value of {path} cannot be used; its default is used.": "การตั้งค่า: ใช้ค่าของ {path} ไม่ได้ จึงใช้ค่าเริ่มต้นแทน",
  "Settings: the value of {path} cannot be used; the drawing keeps its current value.": "การตั้งค่า: ใช้ค่าของ {path} ไม่ได้ ภาพวาดจึงคงค่าปัจจุบันไว้",
  "Settings: the value of {path} cannot be used; {used} is used.": "การตั้งค่า: ใช้ค่าของ {path} ไม่ได้ จึงใช้ {used} แทน",
  "Settings: {count} entries of {path} could not be read and were dropped.": "การตั้งค่า: รายการใน {path} จำนวน {count} รายการอ่านไม่ได้จึงทิ้งไป",
  "Settings: {count} entry of {path} could not be read and was dropped.": "การตั้งค่า: รายการใน {path} จำนวน {count} รายการอ่านไม่ได้จึงทิ้งไป",
  "Settings: {path} names a file or record this Session does not hold; it is left out.": "การตั้งค่า: {path} ระบุไฟล์หรือระเบียนที่ไม่มีในเซสชันนี้จึงละเว้นไว้",
  "Several candidates": "มีฟีเจอร์ที่เข้าข่ายหลายรายการ",
  "Shaft Width Ratio": "อัตราส่วนความกว้างก้านลูกศร",
  "Shaft thickness divided by the full rendered feature thickness. Enter a value greater than 0 and at most 1: 1 keeps a full-width body, while smaller values narrow the shaft. Short arrows may render as triangles.": "ความหนาของก้านลูกศรหารด้วยความหนาทั้งหมดของฟีเจอร์ที่วาด ป้อนค่าที่มากกว่า 0 และไม่เกิน 1: ค่า 1 จะคงตัวลูกศรเต็มความกว้าง ส่วนค่าที่น้อยกว่าจะทำให้ก้านแคบลง ลูกศรที่สั้นอาจแสดงเป็นรูปสามเหลี่ยม",
  "Shared Y-axis": "แกน Y ร่วม",
  "Shift features radially to avoid overlap.": "เลื่อนฟีเจอร์ในแนวรัศมีเพื่อหลีกเลี่ยงการซ้อนทับ",
  "Shifted by (bp)": "ระยะเลื่อน (bp)",
