  "Show Labels": "แสดงป้ายกำกับ",
  "Show Multi-Record Canvas setting": "แสดงการตั้งค่าแคนวาสหลายระเบียน",
  "Show depth coverage axis tick marks and x-coverage labels.": "แสดงขีดของแกนความลึกและป้ายกำกับ coverage (x)",
