  "Show on the diagram": "แสดงบนแผนภาพ",
  "Show only a sub-region (1-based, inclusive). For multi-record files, specify the record ID or #<number>. A region that reaches past the record end is drawn to the record end.": "แสดงเฉพาะบริเวณย่อย (เริ่มนับที่ 1 และรวมปลายทั้งสองด้าน) สำหรับไฟล์ที่มีหลายระเบียน ให้ระบุรหัสระเบียนหรือ #<number> บริเวณที่เกินท้ายระเบียนจะวาดถึงท้ายระเบียน",
  "Show or hide the feature search bar": "แสดงหรือซ่อนแถบค้นหาฟีเจอร์",
  "Show pair": "แสดงคู่",
  "Show pair {pair}": "แสดงคู่ {pair}",
  "Show primary coordinate ticks and labels in simple mode. The circular genome axis remains visible when this is off.": "แสดงขีดพิกัดหลักและป้ายกำกับในโหมดแบบง่าย แกนจีโนมของแผนภาพแบบวงกลมยังคงแสดงอยู่เมื่อปิดตัวเลือกนี้",
  "Show stroke options": "แสดงตัวเลือกเส้นขอบ",
  "Show the GC content percent axis line. Hiding the axis also hides percent tick marks and labels.": "แสดงเส้นแกนเปอร์เซ็นต์ของปริมาณ GC การซ่อนแกนจะซ่อนขีดและป้ายกำกับเปอร์เซ็นต์ด้วย",
  "Show the bottom scale bar or ruler and any coordinate ticks and labels drawn on record axes. Main record axes remain visible when this is off.": "แสดงแถบมาตราส่วนหรือไม้บรรทัดด้านล่าง และขีดพิกัดกับป้ายกำกับที่วาดบนแกนของระเบียน แกนหลักของระเบียนยังคงแสดงอยู่เมื่อปิดตัวเลือกนี้",
  "Show the depth coverage axis line. Hiding the axis also hides depth tick marks and labels.": "แสดงเส้นแกนความลึก การซ่อนแกนจะซ่อนขีดและป้ายกำกับความลึกด้วย",
  "Show the label editor": "แสดงเครื่องมือแก้ไขป้ายกำกับ",
  "Show the members of {id}": "แสดงสมาชิกของ {id}",
