  "Similarity groups and Collinear blocks compare every adjacent pair with LOSAT.": "กลุ่มความคล้ายคลึงและบล็อก Collinear เปรียบเทียบทุกคู่ที่อยู่ติดกันด้วย LOSAT",
  "Similarity groups appear after a Linear comparison with Similarity groups turned on.": "กลุ่มความคล้ายคลึงจะปรากฏหลังจากการเปรียบเทียบแบบเส้นตรง โดยเปิด “กลุ่มความคล้ายคลึง” ไว้",
  "Similarity groups: {count} description edit ({path}) names a group the saved Result does not have and was dropped.": "กลุ่มความคล้ายคลึง: การแก้ไขคำอธิบายกลุ่ม {count} รายการ ({path}) ระบุกลุ่มที่ไม่มีในผลลัพธ์ที่บันทึกไว้จึงทิ้งไป",
  "Similarity groups: {count} description edits ({path}) name a group the saved Result does not have and were dropped.": "กลุ่มความคล้ายคลึง: การแก้ไขคำอธิบายกลุ่ม {count} รายการ ({path}) ระบุกลุ่มที่ไม่มีในผลลัพธ์ที่บันทึกไว้จึงทิ้งไป",
  "Similarity groups: {count} name edit ({path}) names a group the saved Result does not have and was dropped.": "กลุ่มความคล้ายคลึง: การแก้ไขชื่อ {count} รายการ ({path}) ระบุกลุ่มที่ไม่มีในผลลัพธ์ที่บันทึกไว้จึงทิ้งไป",
  "Similarity groups: {count} name edits ({path}) name a group the saved Result does not have and were dropped.": "กลุ่มความคล้ายคลึง: การแก้ไขชื่อ {count} รายการ ({path}) ระบุกลุ่มที่ไม่มีในผลลัพธ์ที่บันทึกไว้จึงทิ้งไป",
