  "Simple mode only. Above places features above the axis, Features on axis centers them on it, and Below places them below it. Use Reset to copy this choice into the custom stack.": "เฉพาะโหมดแบบง่าย “ด้านบน” วางฟีเจอร์เหนือแกน “ฟีเจอร์บนแกน” วางฟีเจอร์คร่อมแกนให้อยู่กึ่งกลาง และ “ด้านล่าง” วางฟีเจอร์ใต้แกน ใช้ “รีเซ็ต” เพื่อคัดลอกตัวเลือกนี้ลงในสแต็กที่กำหนดเอง",
  "Simple mode only. Display a GC content track; use Reset to copy it into the custom stack.": "เฉพาะโหมดแบบง่าย แสดงแทร็กปริมาณ GC ใช้ “รีเซ็ต” เพื่อคัดลอกแทร็กนี้ลงในสแต็กที่กำหนดเอง",
  "Simple mode only. Display a GC skew track; use Reset to copy it into the custom stack.": "เฉพาะโหมดแบบง่าย แสดงแทร็ก GC skew ใช้ “รีเซ็ต” เพื่อคัดลอกแทร็กนี้ลงในสแต็กที่กำหนดเอง",
  "Simple mode only. Display depth coverage tracks from uploaded TSV files; use Reset to copy them into the custom stack.": "เฉพาะโหมดแบบง่าย แสดงแทร็กความลึก (coverage) จากไฟล์ TSV ที่อัปโหลด ใช้ “รีเซ็ต” เพื่อคัดลอกแทร็กเหล่านี้ลงในสแต็กที่กำหนดเอง",
  "Simple mode only. Use Reset to rebuild the custom stack from this setting.": "เฉพาะโหมดแบบง่าย ใช้ “รีเซ็ต” เพื่อสร้างสแต็กที่กำหนดเองใหม่จากการตั้งค่านี้",
