  "The Default colors, Specific rules, Blacklist, Whitelist, and Priority files, with the settings they loaded": "ไฟล์สีเริ่มต้น กฎเฉพาะ บัญชีดำ บัญชีขาว และลำดับความสำคัญ พร้อมการตั้งค่าที่โหลดจากไฟล์เหล่านั้น",
