  "Tick label layout {id}": "เลย์เอาต์ป้ายกำกับขีด {id}",
  "Ticks": "ขีด",
  "Ticks only": "เฉพาะขีด",
  "Titles": "ชื่อเรื่อง",
  "Titles & Record Labels": "ชื่อเรื่องและป้ายกำกับระเบียน",
  "Titles and Record Labels": "ชื่อเรื่องและป้ายกำกับระเบียน",
  "To #{n}": "ไปยัง #{n}",
  "To make room, do one of the following.": "เพื่อเพิ่มพื้นที่ ให้ทำอย่างใดอย่างหนึ่งต่อไปนี้",
