  "To record for unplaced comparison {id}": "ระเบียนปลายทางของการเปรียบเทียบที่ยังไม่ได้วาง {id}",
  "To reorder, drag a row by its grip, or focus the grip and press the Up or Down arrow.": "หากต้องการจัดลำดับใหม่ ให้ลากแถวโดยใช้ที่จับ หรือโฟกัสที่จับแล้วกดแป้นลูกศรขึ้นหรือลง",
  "Toggle canvas padding controls": "เปิด/ปิดตัวควบคุมระยะเว้นขอบแคนวาส",
