  "Top Similarity Group Record": "ระเบียนบนสุดของกลุ่มความคล้ายคลึง",
  "Topology and display start": "โทโพโลยีและตำแหน่งเริ่มแสดงผล",
  "Total threads": "จำนวนเธรดทั้งหมด",
  "Track ID '{id}' is used by more than one enabled row.": "มีแถวที่เปิดใช้อยู่มากกว่า 1 แถวใช้รหัสแทร็ก “{id}”",
