  "When enabled, feature clicks show Details, Qualifiers, and Sequence tabs. Disable for the compact edit-only popup.": "เมื่อเปิดใช้ การคลิกฟีเจอร์จะแสดงแท็บ “รายละเอียด” “qualifier” และ “ลำดับ” ปิดใช้เพื่อใช้ป๊อปอัปแบบกะทัดรัดสำหรับแก้ไขเท่านั้น",
