  "Window size for depth aggregation. Blank: a tenth of the GC window, at least 100 bp.": "ขนาดหน้าต่างสำหรับการรวมค่าความลึก หากเว้นว่าง จะใช้หนึ่งในสิบของขนาดหน้าต่าง GC แต่ไม่น้อยกว่า 100 bp",
  "Yes": "ใช่",
  "Your custom track stack has {count} GC content track. Hiding GC content turns that track off.": "สแต็กแทร็กที่กำหนดเองของคุณมีแทร็กปริมาณ GC {count} แทร็ก การซ่อนปริมาณ GC จะปิดแทร็กดังกล่าว",
