  "{count} Feature visibility edit from an older Session hid every feature with the same hash, such as each copy of a duplicated record. It now applies only to the feature that was edited, so the next Generate draws the others.": "การแก้ไขการมองเห็นฟีเจอร์ {count} รายการจากเซสชันเก่าซ่อนทุกฟีเจอร์ที่มีแฮชเดียวกัน เช่น ทุกสำเนาของระเบียนที่ซ้ำกัน ตอนนี้การแก้ไขแต่ละรายการมีผลเฉพาะกับฟีเจอร์ที่แก้ไข การสร้างครั้งถัดไปจึงจะวาดฟีเจอร์อื่นๆ ด้วย",
  "{count} Feature visibility edits from an older Session hid every feature with the same hash, such as each copy of a duplicated record. Each now applies only to the feature that was edited, so the next Generate draws the others.": "การแก้ไขการมองเห็นฟีเจอร์ {count} รายการจากเซสชันเก่าซ่อนทุกฟีเจอร์ที่มีแฮชเดียวกัน เช่น ทุกสำเนาของระเบียนที่ซ้ำกัน ตอนนี้การแก้ไขแต่ละรายการมีผลเฉพาะกับฟีเจอร์ที่แก้ไข การสร้างครั้งถัดไปจึงจะวาดฟีเจอร์อื่นๆ ด้วย",
  "{count} LOSAT result is cached and reused when the inputs and settings match.": "มีผล LOSAT ในแคช {count} รายการ ซึ่งจะนำมาใช้ซ้ำเมื่ออินพุตและการตั้งค่าตรงกัน",
  "{count} LOSAT results are cached and reused when the inputs and settings match.": "มีผล LOSAT ในแคช {count} รายการ ซึ่งจะนำมาใช้ซ้ำเมื่ออินพุตและการตั้งค่าตรงกัน",
