  "{count} aligned": "จัดแนวแล้ว {count} ระเบียน",
  "{count} annotation from an older Session named a feature by hash=. It now names that feature by its source, so it stays on the feature when the crop or orientation changes.": "คำอธิบายประกอบ {count} รายการจากเซสชันเก่าระบุฟีเจอร์ด้วย hash= ตอนนี้คำอธิบายประกอบแต่ละรายการระบุฟีเจอร์นั้นด้วยระเบียนต้นทาง จึงยังอยู่บนฟีเจอร์เดิมเมื่อการครอบตัดหรือทิศทางเปลี่ยน",
  "{count} annotation of a selected feature that the current diagram does not draw was not exported.": "ไม่ได้ส่งออกคำอธิบายประกอบ {count} รายการของฟีเจอร์ที่เลือกซึ่งแผนภาพปัจจุบันไม่ได้วาด",
  "{count} annotation of a selected feature was written as record=#<position> and feature_selector=hash=<feature hash>. It names the same feature only while the record order stays as drawn.": "เขียนคำอธิบายประกอบ {count} รายการของฟีเจอร์ที่เลือกเป็น record=#<position> และ feature_selector=hash=<feature hash> แล้ว คำอธิบายประกอบเหล่านี้จะระบุฟีเจอร์เดิมได้ ก็ต่อเมื่อลำดับระเบียนยังคงเหมือนที่วาดไว้",
  "{count} annotations from an older Session named a feature by hash=. Each now names that feature by its source, so it stays on the feature when the crop or orientation changes.": "คำอธิบายประกอบ {count} รายการจากเซสชันเก่าระบุฟีเจอร์ด้วย hash= ตอนนี้คำอธิบายประกอบแต่ละรายการระบุฟีเจอร์นั้นด้วยระเบียนต้นทาง จึงยังอยู่บนฟีเจอร์เดิมเมื่อการครอบตัดหรือทิศทางเปลี่ยน",
